add_claim("THE STAGED-STADIUM STRATEGY: 'I upgraded my stadiums to **just enough for each division** and stopped playing career after three promotions until I liked my team.' So the stadium only has to clear the next gate, not the final one - which frees coins for players while you climb.", 3, "career/staged-stadium-strategy", [e_cg])
add_claim("THE COMMERCIAL UPGRADE PAYS BACK WITHIN A SEASON: 'Spend 75 gems to upgrade your commercial facility... **You'll get the gems back by the end of the season** if you win and complete objectives. You can also wait a season before upgrading.' So the 75-gem Commercial level 1 is a season-length loan, not a permanent sink.", 3, "facilities/commercial-l1-pays-back-in-a-season", [e_cg])
add_claim("A SECOND RECOMMENDATION TO CAMP HIGH TIERS FOR EVENTS: 'For online, **stay in tiers 18-20, and play events** (this gets you easier event matches)' - and to build the stadium **roofless** 'so it costs less money.' Two corroborations for existing corpus rules, from independent threads.", 3, "dll/camp-high-tiers-for-easier-events", [e_cg])

for p in ['EV-502_career_gem_model.html','EV-502b_clan_ladder.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
